import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import { RateLimiterMemory } from 'rate-limiter-flexible';

const app = express();
app.use(express.json());

// Rate limiter configuration
const rateLimiter = new RateLimiterMemory({
  points: 10,
  duration: 60,
});

// Encryption service for mobile API tokens
class TokenEncryptionService {
  private masterKey: Buffer;
  private algorithm = 'aes-256-gcm';
  private ivLength = 12;
  private tagLength = 16;

  constructor(masterKeyHex: string) {
    this.masterKey = Buffer.from(masterKeyHex, 'hex');
  }

  // Derive a per-purpose key from master key
  private deriveKey(purpose: string): Buffer {
    return crypto.createHmac('sha256', this.masterKey)
      .update(purpose)
      .digest();
  }

  // Generate deterministic IV for idempotent encryption
  // Used for retry-safe token generation
  private generateIV(requestId: string, attempt: number): Buffer {
    const hmac = crypto.createHmac('sha256', this.masterKey);
    hmac.update(`${requestId}:${attempt}`);
    return hmac.digest().subarray(0, this.ivLength);
  }

  encrypt(plaintext: string, purpose: string, requestId: string, attempt: number): string {
    const key = this.deriveKey(purpose);
    const iv = this.generateIV(requestId, attempt);
    const cipher = crypto.createCipheriv(this.algorithm, key, iv);
    cipher.setAAD(Buffer.from(purpose));
    const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return Buffer.concat([iv, tag, encrypted]).toString('base64url');
  }

  decrypt(ciphertext: string, purpose: string): string {
    const key = this.deriveKey(purpose);
    const data = Buffer.from(ciphertext, 'base64url');
    const iv = data.subarray(0, this.ivLength);
    const tag = data.subarray(this.ivLength, this.ivLength + this.tagLength);
    const encrypted = data.subarray(this.ivLength + this.tagLength);
    const decipher = crypto.createDecipheriv(this.algorithm, key, iv);
    decipher.setAAD(Buffer.from(purpose));
    decipher.setAuthTag(tag);
    return decipher.update(encrypted) + decipher.final('utf8');
  }
}

// Retry handler for mobile clients with poor connectivity
class RetryHandler {
  private pendingRequests: Map<string, { attempt: number; lastResult: string }> = new Map();

  getAttempt(requestId: string): number {
    const existing = this.pendingRequests.get(requestId);
    if (existing) {
      return existing.attempt;
    }
    return 0;
  }

  recordAttempt(requestId: string, result: string): void {
    const existing = this.pendingRequests.get(requestId);
    const attempt = existing ? existing.attempt + 1 : 1;
    this.pendingRequests.set(requestId, { attempt, lastResult: result });
  }

  getCachedResult(requestId: string): string | null {
    return this.pendingRequests.get(requestId)?.lastResult || null;
  }
}

const MASTER_KEY = crypto.randomBytes(32).toString('hex');
const encryptionService = new TokenEncryptionService(MASTER_KEY);
const retryHandler = new RetryHandler();

// Rate limiting middleware
async function rateLimitMiddleware(req: Request, res: Response, next: NextFunction) {
  try {
    const clientId = req.headers['x-client-id'] as string || req.ip;
    await rateLimiter.consume(clientId);
    next();
  } catch (e) {
    res.status(429).json({ error: 'Too many requests' });
  }
}

// Token issuance endpoint for mobile auth
app.post('/api/v1/token/issue', rateLimitMiddleware, (req: Request, res: Response) => {
  const { userId, deviceId, requestId } = req.body;

  if (!userId || !deviceId || !requestId) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Check for retry - return cached result for idempotency
  const cached = retryHandler.getCachedResult(requestId);
  if (cached) {
    return res.json({ token: cached, fromCache: true });
  }

  const attempt = retryHandler.getAttempt(requestId);
  const tokenPayload = JSON.stringify({
    sub: userId,
    dev: deviceId,
    iat: Math.floor(Date.now() / 1000),
    jti: requestId
  });

  // Encrypt token with purpose-bound key
  // The attempt parameter ensures retry-safe deterministic encryption
  const encryptedToken = encryptionService.encrypt(
    tokenPayload,
    'mobile-auth-token',
    requestId,
    attempt
  );

  retryHandler.recordAttempt(requestId, encryptedToken);
  res.json({ token: encryptedToken, fromCache: false });
});

// Token refresh endpoint
app.post('/api/v1/token/refresh', rateLimitMiddleware, (req: Request, res: Response) => {
  const { token, requestId } = req.body;

  if (!token || !requestId) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  try {
    const payload = encryptionService.decrypt(token, 'mobile-auth-token');
    const parsed = JSON.parse(payload);

    const attempt = retryHandler.getAttempt(requestId);
    const newPayload = JSON.stringify({
      ...parsed,
      iat: Math.floor(Date.now() / 1000),
      jti: requestId
    });

    const newToken = encryptionService.encrypt(
      newPayload,
      'mobile-auth-token',
      requestId,
      attempt
    );

    retryHandler.recordAttempt(requestId, newToken);
    res.json({ token: newToken });
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
});

export default app;
